package domaindns

import("context";"errors";"strings")
type Domain struct{ID string `json:"id"`;Name string `json:"name"`;Status string `json:"status"`;DNSSEC bool `json:"dnssec"`;Nameservers []string `json:"nameservers,omitempty"`}
type Record struct{ID string `json:"id"`;Zone string `json:"zone"`;Name string `json:"name"`;Type string `json:"type"`;Value string `json:"value"`;TTL uint32 `json:"ttl"`;Priority uint16 `json:"priority,omitempty"`}
type DomainStore interface{ListDomains(context.Context)([]Domain,error);GetDomain(context.Context,string)(Domain,error);ListRecords(context.Context,string)([]Record,error);CreateRecord(context.Context,Record)error;DeleteRecord(context.Context,string)error}
func ValidateDomain(d Domain)error{name:=strings.TrimSuffix(strings.ToLower(strings.TrimSpace(d.Name)),".");if strings.TrimSpace(d.ID)==""||name==""{return errors.New("domain id and name are required")};if len(name)>253||strings.ContainsAny(name," \t\r\n/")||strings.HasPrefix(name,"."){return errors.New("invalid domain name")};for _,label:=range strings.Split(name,"."){if len(label)==0||len(label)>63||label[0]=='-'||label[len(label)-1]=='-'{return errors.New("invalid domain name")};for _,r:=range label{if !((r>='a'&&r<='z')||(r>='0'&&r<='9')||r=='-'||r>=128){return errors.New("invalid domain name")}}};return nil}
func ValidateRecord(r Record)error{if strings.TrimSpace(r.ID)==""||strings.TrimSpace(r.Zone)==""||strings.TrimSpace(r.Name)==""||strings.TrimSpace(r.Type)==""||strings.TrimSpace(r.Value)==""{return errors.New("record id, zone, name, type and value are required")};if r.TTL==0||r.TTL>604800{return errors.New("record TTL must be between 1 and 604800")};if len(strings.TrimSpace(r.Value))>1<<20{return errors.New("record value is too large")};if len(strings.TrimSpace(r.Type))>16{return errors.New("record type is too large")};return nil}
